{
  "title": "社团的秘密",
  "scene": "你刚刚结束了紧张的期末考试，决定去社团活动室放松一下。走到门口，你发现门半开着，里面传来轻微的争执声。透过门缝，你隐约看到社长小林正和另一位成员小王激烈争论着什么，桌上摆着一本被翻得很旧的笔记本。两人似乎没有注意到你的到来。你意识到，这可能是解开社团内部矛盾的关键时刻。",
  "goal": "找出争执的原因并帮助解决",
  "clue": "笔记本在争执的桌子上，且被翻得很旧，暗示其重要性",
  "choices": [
    {
      "id": "A",
      "text": "敲门直接进入",
      "outcome": "你敲门后，两人迅速分开，小林一脸不悦地迎接你。他告诉你笔记本是社团的机密文件，不能外传。由于你的贸然行动，小林对你产生了不信任，后续的社团活动不再邀请你参加。",
      "result": "fail",
      "next": "next_level"
    },
    {
      "id": "B",
      "text": "偷听他们的对话",
      "outcome": "你悄悄靠近门口，听到小林说笔记本里记录了社团成立以来的所有活动记录和经费使用情况。小王认为某些经费使用不透明，要求查看。你决定利用这个信息，找到一个更巧妙的解决办法。",
      "result": "partial",
      "next": "retry"
    },
    {
      "id": "C",
      "text": "找机会翻阅笔记本",
      "outcome": "你假装去找社团的备用钥匙，趁两人不注意时迅速翻阅了笔记本。你发现小王提出质疑的经费确实有记录，但金额和用途清晰。你将这个发现告诉小王，消除了误会，两人握手言欢。你机智地解决了争端，获得了社团成员的信任。",
      "result": "success",
      "next": "next_level"
    }
  ]
}
